def is_balanced(s: str) -> bool:
    stack = []
    bracket_map = {")": "(", "}": "{", "]": "["}
    for c in s:
        if c in bracket_map.values():
            stack.append(c)
        elif c in bracket_map.keys():
            if not stack or stack[-1]!= bracket_map[c]):
                return False
            stack.pop()
    return len(stack) == 0

