def checkBrackets(s) {
    let stack = [];
    for (let i = 0; i < s.length; i++) {
        if (s[i] == '(' || s[i] == '[')) {
            stack.push(s[i]);
        } else if (s[i] == ')') {
            if (stack.length == 0) {
                return false;
            }
            stack.pop();
        } else if (s[i] == '[')) {
            stack.pop();
        }
    }
    return stack.length == 0;
}

