def most_frequent_words(text: str, n: int) -> list[str]:
    words = text.split(" ")
    if n <= 0:
        raise ValueError("n must be positive")
    if n > len(words):
        raise ValueError("n must not be greater than the number of words")
    frequency = {}
    for word in words:
        if word!= "":
            frequency[word] = frequency.get(word, 0) + 1
    sorted_words = sorted(frequency, key=frequency.get, reverse=True)
    return sorted_words[:n]

