def moving_average(values, window_size):
    if window_size <= 0:
        raise ValueError("window size must be a positive integer")
    if not values:
        return []
    if window_size > len(values):
        return [sum(values) / len(values)] * (window_size - len(values)) + values[-window_size+1:]
    return [sum(values[:i+1])/i for i in range(1, window_size)] + [sum(values[i:])/(window_size-i) for i in range(window_size)]

def flatten(lst):
    result = []
    for i in lst:
        if isinstance(i, list):
            result.extend(flatten(i))
        else:
            result.append(i)
    return result

def group_by_key(dicts, key): 
    result = {}
    for d in dicts:
        if key in d:
            k = d[key]
            if k in result:
                result[k].append(d)
            else:
                result[k] = [d]
    return result
